  zones.forEach(function (o) { o.ring.forEach(function (p) { pts.push(p); }); });
  lines.forEach(function (o) { o.ring.forEach(function (p) { pts.push(p); }); });
  markers.forEach(function (m) { pts.push([m.lat, m.lng]); });
