      ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(20,30,12,0.6)'; ctx.stroke();
      ctx.lineWidth = 1.4; ctx.strokeStyle = 'rgba(226,189,96,0.95)'; ctx.stroke();
      ctx.beginPath(); ctx.arc(t[0], t[1], 3.2, 0, Math.PI * 2);
